#include <iostream>
#include <vector>
#include <queue>
#include <cstring>
using namespace std;

const int MAXN = 200;
const int MAXM = 100000;
const int INF = 200000000;

int maze[20][20];
int graph[MAXN][MAXN];
int n, N, t;
string s;
int hu[MAXN][3], re[MAXN][3];
int zr, zc;
int cx, cy;
int directions[4][2] = {{0, -1}, {0, 1}, {-1, 0}, {1, 0}};

int getIndex(int r, int c) {
    if (r > 0 && r <= n && c > 0 && c <= n && maze[r][c] != -1)
        return (r - 1) * n + c;
    return -1;
}

void buildGraph() {
    N = n * n;
    memset(graph, -1, sizeof(graph));
    for (int r1 = 1; r1 <= n; r1++) {
        for (int c1 = 1; c1 <= n; c1++) {
            if (maze[r1][c1] == -1) continue;
            int p1 = (r1 - 1) * n + c1;
            graph[p1][p1] = 0;
            for (int i = 0; i < 4; i++) {
                int r2 = r1 + directions[i][0];
                int c2 = c1 + directions[i][1];
                if (r2 > 0 && r2 <= n && c2 > 0 && c2 <= n && maze[r2][c2] != -1) {
                    int p2 = (r2 - 1) * n + c2;
                    graph[p1][p2] = 1;
                }
            }
        }
    }
}

int dist[MAXN];
int queue[MAXM];

void shortestPath() {
    int front = 0, rear = 1;
    for (int i = 1; i <= N; i++) dist[i] = INF;
    int start = (zr - 1) * n + zc;
    dist[start] = 0;
    queue[0] = start;
    while (front < rear) {
        int current = queue[front++];
        for (int i = 1; i <= N; i++) {
            if (graph[current][i] == 1 && dist[i] > dist[current] + 1) {
                dist[i] = dist[current] + 1;
                queue[rear++] = i;
            }
        }
    }
}

void floydWarshall() {
    for (int k = 1; k <= N; k++) {
        for (int i = 1; i <= N; i++) {
            for (int j = 1; j <= N; j++) {
                if (graph[i][k] != -1 && graph[k][j] != -1) {
                    if (graph[i][j] == -1 || graph[i][j] > graph[i][k] + graph[k][j]) {
                        graph[i][j] = graph[i][k] + graph[k][j];
                    }
                }
            }
        }
    }
}

struct Edge {
    int st, ed, flow, next;
};

vector<Edge> edges;
int head[MAXN], edgeCount;
int source, sink;

void addEdge(int st, int ed, int flow) {
    edges.push_back({st, ed, flow, head[st]});
    head[st] = (int)edges.size() - 1;
    edges.push_back({ed, st, 0, head[ed]});
    head[ed] = (int)edges.size() - 1;
}

int level[MAXN];

bool bfs() {
    memset(level, -1, sizeof(level));
    level[source] = 0;
    queue[0] = source;
    int front = 0, rear = 1;
    while (front < rear) {
        int u = queue[front++];
        for (int i = head[u]; i != -1; i = edges[i].next) {
            int v = edges[i].ed;
            if (edges[i].flow > 0 && level[v] == -1) {
                level[v] = level[u] + 1;
                queue[rear++] = v;
            }
        }
    }
    return level[sink] != -1;
}

int ptr[MAXN];

int dfs(int u, int flow) {
    if (u == sink) return flow;
    for (int &i = ptr[u]; i != -1; i = edges[i].next) {
        int v = edges[i].ed;
        if (edges[i].flow > 0 && level[v] == level[u] + 1) {
            int pushed = dfs(v, min(flow, edges[i].flow));
            if (pushed > 0) {
                edges[i].flow -= pushed;
                edges[i ^ 1].flow += pushed;
                return pushed;
            }
        }
    }
    return 0;
}

int maxFlow() {
    int total = 0;
    while (bfs()) {
        for (int i = 0; i <= N + 1; i++) ptr[i] = head[i];
        while (int pushed = dfs(source, INF))
            total += pushed;
    }
    return total;
}

int solve() {
    maze[zr][zc] = 0;
    buildGraph();
    shortestPath();
    maze[zr][zc] = -1;
    buildGraph();
    floydWarshall();
    // Build flow network
    edges.clear();
    memset(head, -1, sizeof(head));
    edgeCount = 0;
    source = 0;
    sink = cx + cy + 1;
    for (int i = 1; i <= cx; i++) {
        addEdge(source, i, hu[i][2]);
    }
    for (int i = 1; i <= cy; i++) {
        addEdge(cx + i, sink, re[i][2]);
    }
    int p = (zr - 1) * n + zc;
    for (int i = 1; i <= cx; i++) {
        for (int j = 1; j <= cy; j++) {
            int p1 = (hu[i][0] - 1) * n + hu[i][1];
            int p2 = (re[j][0] - 1) * n + re[j][1];
            if (graph[p1][p2] != -1 && graph[p1][p2] <= t && graph[p1][p2] < dist[p2]) {
                addEdge(i, cx + j, INF);
            } else if (graph[p1][p2] != -1 && graph[p1][p2] <= t && graph[p1][p2] == dist[p2]) {
                for (int z = 0; z < 4; z++) {
                    int rr = re[j][0] + directions[z][0];
                    int cc = re[j][1] + directions[z][1];
                    int pp = getIndex(rr, cc);
                    if (pp != -1) {
                        if (graph[p1][pp] == graph[p1][p2] - 1 && graph[p1][pp] < dist[pp]) {
                            addEdge(i, cx + j, INF);
                        }
                    }
                }
            }
        }
    }
    return maxFlow();
}

int main() {
    cin >> n >> t;
    cx = cy = 0;
    memset(maze, 0, sizeof(maze));
    for (int i = 1; i <= n; i++) {
        cin >> s;
        for (int j = 0; j < n; j++) {
            if (s[j] == 'Y') maze[i][j + 1] = -1;
            else if (s[j] == 'Z') {
                zr = i; zc = j + 1;
                maze[i][j + 1] = -1;
            } else if (s[j] > '0' && s[j] <= '9') {
                hu[++cx][0] = i;
                hu[cx][1] = j + 1;
                hu[cx][2] = s[j] - '0';
            }
        }
    }
    for (int i = 1; i <= n; i++) {
        cin >> s;
        for (int j = 0; j < n; j++) {
            if (s[j] > '0' && s[j] <= '9') {
                re[++cy][0] = i;
                re[cy][1] = j + 1;
                re[cy][2] = s[j] - '0';
            }
        }
    }
    cout << solve() << endl;
    return 0;
}
